-- 2026-10-w3 G2: C71 の情景を「光源なし・形は見分けられる暗さ」へ(2 回目が暗すぎたため)
-- C71
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "停電の夜の不思議だ", "hint": "読み方は1つじゃないぞ!", "question": "新月の夜に停電して、家じゅう真っ暗。明かりは1つもないのに、男は分厚い本を最後まで読み続けた。なぜ?", "answer": "目の見えない人で、点字の本を読んでいたから", "explanation": "明かりの代わりを探すと行き詰まる。男は目の見えない人で、指先で点字を読んでいた。暗くても読書には何の問題もなかったのだ。", "coach_comment": "前提をひっくり返したな!", "tags": ["水平思考", "夜の一問", "ひっかけ"], "summary": "新月の夜の停電で真っ暗な家で、明かりもなく分厚い本を最後まで読んだ理由を問う水平思考の定番。答えは目の見えない人が点字の本を読んでいた。", "illustration_scene": "夜、停電した暗い部屋。部屋全体を暗い青灰色の濃淡で描き、ソファに座った男の後ろ姿、膝の上に開いた分厚い本、本棚・ローテーブル・観葉植物の形がはっきり見分けられる。本のページは無地。窓の外は暗い夜空。ランプ・ろうそく・画面などの光源と、光る輪郭はない。男の頭上に大きな「?」。顔・「?」以外の文字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.content_key = 'night-065';
